CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), auth_subject text UNIQUE, display_name text NOT NULL, email text, phone text, is_active boolean NOT NULL DEFAULT true, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, email));
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE CHECK (code IN ('client','project_manager','internal_team_member')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, company text, email text, phone_whatsapp text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, slug text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, slug));
CREATE TABLE IF NOT EXISTS requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), public_reference text NOT NULL UNIQUE, client_id uuid NOT NULL REFERENCES clients(id), service_domain_id uuid NOT NULL REFERENCES service_domains(id), requirement text NOT NULL, urgency text NOT NULL CHECK (urgency IN ('flexible','soon','time_sensitive')), status text NOT NULL DEFAULT 'awaiting_acknowledgement' CHECK (status IN ('awaiting_acknowledgement','acknowledged','in_progress','resolved')), version integer NOT NULL DEFAULT 1, resolved_at timestamptz, resolved_by_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id) ON DELETE CASCADE, assignee_user_id uuid NOT NULL REFERENCES users(id), assigned_by_user_id uuid REFERENCES users(id), assigned_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, end_reason text, created_at timestamptz NOT NULL DEFAULT now(), CHECK (ended_at IS NULL OR ended_at >= assigned_at));
CREATE UNIQUE INDEX IF NOT EXISTS assignments_one_current ON assignments (request_id) WHERE ended_at IS NULL;
CREATE INDEX IF NOT EXISTS assignments_request_idx ON assignments (request_id, assigned_at DESC);
CREATE TABLE IF NOT EXISTS sla_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL UNIQUE REFERENCES assignments(id) ON DELETE CASCADE, policy_code text NOT NULL, duration_seconds integer NOT NULL CHECK (duration_seconds > 0), started_at timestamptz NOT NULL, deadline_at timestamptz NOT NULL, acknowledged_at timestamptz, acknowledged_by_user_id uuid REFERENCES users(id), is_late boolean NOT NULL DEFAULT false, breached_at timestamptz, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','acknowledged','breached','superseded','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (deadline_at >= started_at));
CREATE INDEX IF NOT EXISTS sla_active_deadline_idx ON sla_records (deadline_at) WHERE status = 'active' AND acknowledged_at IS NULL;
CREATE TABLE IF NOT EXISTS escalation_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES requests(id) ON DELETE CASCADE, assignment_id uuid NOT NULL REFERENCES assignments(id), sla_record_id uuid NOT NULL REFERENCES sla_records(id), responsible_user_id uuid NOT NULL REFERENCES users(id), triggered_at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL, policy_code text NOT NULL, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), request_id uuid REFERENCES requests(id) ON DELETE CASCADE, assignment_id uuid REFERENCES assignments(id), sla_record_id uuid REFERENCES sla_records(id), actor_user_id uuid REFERENCES users(id), actor_type text NOT NULL CHECK (actor_type IN ('user','client','system')), event_type text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), previous_state text, new_state text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, correlation_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id text NOT NULL DEFAULT 'anonymous', organization_id uuid NOT NULL REFERENCES organizations(id), method text NOT NULL, route text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response_status integer, response_body jsonb, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, UNIQUE (organization_id, actor_id, method, route, key));
CREATE INDEX IF NOT EXISTS requests_org_status_idx ON requests (organization_id, status);
CREATE INDEX IF NOT EXISTS users_organization_idx ON users (organization_id);
CREATE INDEX IF NOT EXISTS clients_organization_idx ON clients (organization_id);
CREATE UNIQUE INDEX IF NOT EXISTS clients_organization_email_unique ON clients (organization_id, email) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS requests_client_idx ON requests (client_id);
CREATE INDEX IF NOT EXISTS requests_service_domain_idx ON requests (service_domain_id);
CREATE INDEX IF NOT EXISTS assignments_assignee_idx ON assignments (assignee_user_id) WHERE ended_at IS NULL;
CREATE INDEX IF NOT EXISTS escalation_events_request_idx ON escalation_events (request_id, triggered_at DESC);
CREATE INDEX IF NOT EXISTS audit_organization_occurred_idx ON audit_events (organization_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_request_occurred_idx ON audit_events (request_id, occurred_at DESC);
